<?php
require_once __DIR__.'/../app.php';require_once __DIR__.'/../ui.php';require_once __DIR__.'/../records_service.php';require_staff();
$entity=request_string($_GET,'entity')?:'students';$def=entity_definition($entity);
if($def['admin']&&!is_admin()&&$entity!=='subjects')deny();
$canWrite=is_admin()||in_array($entity,['students','enrollments','interventions'],true);
handle_post(function()use($entity){$action=request_string($_POST,'action');if($action==='approve_policy'&&$entity==='grading_policies'){require_admin();$id=positive_id($_POST['id']??null);$p=policy($id);$reason=text_value($_POST,'reason',1000);query('UPDATE grading_policies SET is_approved=1 WHERE id=?',[$id]);audit('policy_approve','grading_policies',$id,'Institutional approval reference: '.$reason,$p,policy($id));}elseif($action==='remove')remove_record($entity,positive_id($_POST['id']??null));elseif($action==='save')save_record($entity,$_POST);else throw new DomainException('Unknown action.');},'records.php?entity='.urlencode($entity));
$edit=null;if(isset($_GET['edit']))$edit=allowed_record($entity,positive_id($_GET['edit']));
$interventionHistory=($entity==='interventions'&&isset($_GET['history']))?allowed_record($entity,positive_id($_GET['history'])):null;
$q=trim(request_string($_GET,'q'));[$where,$params]=record_scope($entity);
$textKeys=array_keys(array_filter($def['fields'],fn($f)=>$f[1]==='text'));
if($q!==''&&$textKeys){$where.=' AND ('.implode(' OR ',array_map(fn($k)=>"r.`$k` LIKE ?",$textKeys)).')';foreach($textKeys as $key)$params[]='%'.$q.'%';}
if($q!==''&&$entity==='enrollments'){$where.=' AND EXISTS(SELECT 1 FROM students s WHERE s.id=r.student_id AND (s.full_name LIKE ? OR s.student_number LIKE ?))';array_push($params,'%'.$q.'%','%'.$q.'%');}
if($q!==''&&$entity==='offerings'){$where.=' AND EXISTS(SELECT 1 FROM subjects su WHERE su.id=r.subject_id AND (su.subject_code LIKE ? OR su.title LIKE ?))';array_push($params,'%'.$q.'%','%'.$q.'%');}
foreach($def['fields']as $key=>$f){if(in_array($f[1],['ref','faculty','offering','student','enum','bool'],true)&&isset($_GET[$key])&&request_string($_GET,$key)!==''){$val=request_string($_GET,$key);if(!array_key_exists($val,record_options($f)))throw new DomainException('Invalid filter.');$where.=" AND r.`$key`=?";$params[]=$val;}}
$dates=date_filters($_GET);if(in_array($entity,['students','enrollments','interventions'],true)){if(isset($dates['from'])){$where.=' AND r.created_at>=?';$params[]=$dates['from'].' 00:00:00';}if(isset($dates['to'])){$where.=' AND r.created_at<=?';$params[]=$dates['to'].' 23:59:59';}}
$page=max(1,(int)($_GET['page']??1));$total=(int)scalar("SELECT COUNT(*) FROM `$entity` r WHERE $where",$params);$page=min($page,max(1,(int)ceil($total/15)));$offset=($page-1)*15;$data=rows("SELECT r.* FROM `$entity` r WHERE $where ORDER BY r.id DESC LIMIT 15 OFFSET $offset",$params);
page_start($def['title'],$total.' records · changes are audited and access is checked on the server.');
if($entity==='grading_policies')echo '<div class="alert alert-info">ISU: 1.00 is highest, 3.00 passes, 5.00 fails. INC is excluded from GWA. Weights and rounding need institutional approval. Policy versions cannot be edited. <a href="'.h(ISU_POLICY_SOURCE).'" target="_blank" rel="noopener">Read Section 18</a></div>';
if($entity==='offerings')echo '<div class="alert alert-info">Legacy offerings remain restricted until an administrator verifies their assignments. Then review each legacy grade on the Grades page.</div>';
?><section class="panel no-print"><form method="get" class="filter-grid"><input type="hidden" name="entity" value="<?=h($entity)?>"><?php input_field('q','Keyword',$q,'search',false);foreach($def['fields']as $key=>$f)if(in_array($f[1],['ref','faculty','offering','enum','bool'],true))select_field($key,$f[0],record_options($f),$_GET[$key]??'',false);if(in_array($entity,['students','enrollments','interventions'],true)){input_field('from','Created from',$_GET['from']??'','date',false);input_field('to','Created to',$_GET['to']??'','date',false);}?><div class="field align-self-end"><button class="btn btn-outline-primary">Filter</button> <a href="records.php?entity=<?=h($entity)?>">Reset</a></div></form></section>
<?php if($canWrite&&($edit||$entity!=='students'||is_admin())):?><details class="panel no-print" <?= $edit?'open':''?>><summary><?= $edit?'Edit record #'.(int)$edit['id']:'Add '.$def['title']?></summary><form method="post" class="form-grid mt-3"><?php csrf_field();?><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><?php foreach($def['fields']as $key=>$f){$value=$edit[$key]??($key==='is_active'?1:($key==='midterm_weight'?50:''));if(in_array($f[1],['ref','faculty','offering','student','enum','bool'],true))select_field($key,$f[0],record_options($f),$value);else input_field($key,$f[0],$value,match($f[1]){'date','optional_date'=>'date','number','decimal'=>'number',default=>'text'},$f[1]!=='optional_date'&&$key!=='notes',in_array($f[1],['number','decimal'],true)?'min="'.$f[2].'" max="'.$f[3].'" step="'.($f[1]==='decimal'?'0.01':'1').'"':'maxlength="'.(is_int($f[2]??null)?$f[2]:5000).'"');}if($entity==='offerings'){input_field('reason','Assignment / legacy review reason','','text',(bool)$edit);if($edit&&$edit['needs_review'])echo '<label class="wide"><input type="checkbox" name="review_confirm" value="1" required> I verified every attached legacy record belongs to this term, section, and faculty.</label>';}?><div class="wide"><button class="btn btn-primary" name="action" value="save">Save record</button><?php if($edit):?> <a href="records.php?entity=<?=h($entity)?>">Cancel</a><?php endif;?></div></form></details><?php endif;?>
<section class="panel"><?php $columns=['id'=>'ID'];foreach($def['fields']as $key=>$f)$columns[$key]=$f[0];if($entity==='offerings')$columns['needs_review']='Needs review';foreach($data as &$r)foreach($def['fields']as $key=>$f)if(in_array($f[1],['ref','faculty','offering','student','enum','bool'],true))$r[$key]=record_options($f)[$r[$key]]??$r[$key];unset($r);data_table($data,$columns,$canWrite?function($r)use($entity){if($entity==='interventions')echo '<a class="btn btn-sm btn-outline-secondary" href="?entity=interventions&history='.(int)$r['id'].'">Follow-up history</a> ';if($entity==='grading_policies'){echo '<form method="post" class="form-grid">';csrf_field();echo '<input type="hidden" name="id" value="'.(int)$r['id'].'"><input name="reason" class="form-control" placeholder="Institutional approval reference" required maxlength="1000"><button class="btn btn-sm btn-outline-primary" name="action" value="approve_policy">Record approval</button></form>';return;}if($entity!=='grading_policies')echo '<a class="btn btn-sm btn-outline-primary" href="?entity='.h($entity).'&edit='.(int)$r['id'].'">Edit</a> ';if(is_admin()||in_array($entity,['enrollments','interventions'],true))post_button('remove',(int)$r['id'],'Archive / remove','Archive this record? Only enrollment without grades can be permanently removed.');}:null);pagination($total,$page);?></section><?php if($interventionHistory){require_once __DIR__.'/../snapshot_ui.php';echo '<section class="panel"><h2>Intervention follow-up history</h2>';foreach(rows("SELECT created_at,full_name,activity_description,before_data,after_data FROM activity_logs WHERE entity='interventions' AND record_id=? ORDER BY id DESC",[$interventionHistory['id']])as $entry){echo '<details class="history-entry"><summary>'.h($entry['created_at'].' · '.$entry['full_name']).'</summary><p>'.h($entry['activity_description']).'</p><div class="two-column"><div><h3 class="h6">Before</h3>';academic_snapshot($entry['before_data']);echo '</div><div><h3 class="h6">After</h3>';academic_snapshot($entry['after_data']);echo '</div></div></details>';}echo '</section>';}page_end();
